import random

def watermark_generate(text, key=&quot;mysecretkey&quot;):
    # 为每10个token插入一个水印“信号”词
    tokens = text.split()
    random.seed(key)
    idxs = random.sample(range(len(tokens)), min(2, len(tokens)&#47;&#47;5))
    for idx in idxs:
        tokens[idx] = tokens[idx] + &quot;[W]&quot;  # 简单插入水印标记
    return &quot; &quot;.join(tokens)

def watermark_detect(text, key=&quot;mysecretkey&quot;):
    tokens = text.split()
    found = [t for t in tokens if &quot;[W]&quot; in t]
    return len(found) &gt;= 1

txt = &quot;这是一条AI生成的文本，用于演示水印检测原理。&quot;
wm_txt = watermark_generate(txt)
print(&quot;带水印文本：&quot;, wm_txt)
print(&quot;检测结果：&quot;, watermark_detect(wm_txt))
跑这个代码发现加水印效果失败了，原代码中水印插入逻辑存在缺陷：当文本分词后token数量较少时，random.sample可能返回空列表导致未插入水印。可以改成下面的这样
def watermark_generate(text, key=&quot;mysecretkey&quot;):
    &quot;&quot;&quot;为文本添加水印&quot;&quot;&quot;
    tokens = text.split()
    if not tokens:  # 空文本处理
        return text

    # 确保至少插入一个水印
    n = len(tokens)
    min_marks = max(1, min(5, n &#47;&#47; 5))  # 水印数量：至少1个，最多5个
    idxs = random.sample(range(n), min_marks)

    # 插入水印标记
    for idx in idxs:
        tokens[idx] = tokens[idx] + &quot;[W]&quot;

    return &quot; &quot;.join(tokens)
